public class Study {
public static java.util.function.IntUnaryOperator addition(int first){java.util.function.IntFunction<java.util.function.IntUnaryOperator> factory=a->b->a-b;return factory.apply(first);}public static java.util.function.Predicate<String> matcher(String regex){java.util.function.Function<String,java.util.function.Predicate<String>> factory=r->s->s.matches(r);return factory.apply(regex);}public static java.util.function.Function<String,String[]> splitter(String regex){java.util.function.Function<String,java.util.function.Function<String,String[]>> factory=r->s->s.split(r,-1);return factory.apply(regex);}public static void main(String[] args){var plus=addition(7);System.out.println(plus.applyAsInt(-2));System.out.println(plus.applyAsInt(3));var test=matcher("[A-Z]+");System.out.println(test.test("ABC"));System.out.println(test.test("Ab"));var split=splitter(",");for(String s:new String[]{"a,,b,",""}){var parts=split.apply(s);System.out.println(java.util.Arrays.toString(parts)+" length="+parts.length);}}
}
